12	enum class NanPolicy : int { kNone = 0, kZero = 1, kPropagate = 2 };
13	
14	// =========================================================================
15	//  Stage-1 NaN/Inf gradient sanitization (Phase 8) — gfx942 mirror of the
16	//  sm_90 mechanism (grokking_optimizers/kernels/sm_90/common_sm90.cuh).
17	//
18	//  When enabled, a non-finite gradient is treated as 0 BEFORE the per-element
19	//  step reads it (nan_to_num(nan=0,posinf=0,neginf=0) semantics at the gradient
20	//  read boundary only — the optimizer math stays single-sourced). The default
21	//  is OFF, so sg_sanitize_grad() is the identity and the device kernels are
22	//  byte-for-byte the prior behavior; build with -DSG_SANITIZE_NONFINITE=1 to
23	//  turn it on for every gfx942 optimizer apply kernel. Cheap: at most one
24	//  __builtin_isfinite-select per element on the hot path.
25	// =========================================================================
26	#ifndef SG_SANITIZE_NONFINITE
27	#define SG_SANITIZE_NONFINITE 0
28	#endif
29	
30	// Returns g when finite, else 0. Identity (zero added instructions) when OFF.
31	__device__ __forceinline__ float sg_sanitize_grad(float g) {
32	#if SG_SANITIZE_NONFINITE
33	    return __builtin_isfinite(g) ? g : 0.0f;
34	#else
35	    return g;
36	#endif
37	}
