57	template <NanPolicy NP>
58	__forceinline__ __device__ float apply_nan_policy(float g) {
59	    if constexpr (NP == NanPolicy::kZero) {
60	        return __builtin_isnan(g) ? 0.0f : g;
61	    } else {
62	        return g;
63	    }
64	}
