66	template <bool ENABLE_CLIP>
67	__forceinline__ __device__ float apply_clip(float g, float clip_threshold) {
68	    if constexpr (ENABLE_CLIP) {
69	        return fminf(fmaxf(g, -clip_threshold), clip_threshold);
70	    } else {
71	        (void)clip_threshold;
72	        return g;
73	    }
74	}
