66	void launch_grokfast_step(
67	    std::vector<torch::Tensor>& params,
68	    std::vector<torch::Tensor>& exp_avgs,
69	    std::vector<torch::Tensor>& exp_avg_sqs,
70	    std::vector<torch::Tensor>& emas,
71	    std::vector<torch::Tensor>& grads,
72	    float gf_alpha, float gf_lamb,
73	    float lr, float beta1, float beta2, float eps, float wd,
74	    float bc1, float bc2
75	) {
76	    for (size_t i = 0; i < params.size(); i++) {
77	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
78	        auto& p = params[i];
79	        auto& g = grads[i];
80	        auto& m = exp_avgs[i];
81	        auto& v = exp_avg_sqs[i];
82	        auto& ema = emas[i];
83	
84	#if defined(__HIPCC__)
85	        // LIVE device path: dispatch the §5 AMDGCN kernel per tensor (fuses the
86	        // EMA filter + amplification + m/v Adam EMAs + bias-corrected decoupled-
87	        // WD apply into ONE launch). 🟡 hipcc-only — none in this env.
88	        // 64-bit safe element count + grid sizing (Stage 1): numel can exceed
89	        // 2^31, so form n and the block count in int64 then clamp to the 1024-
90	        // workgroup cap. Mirrors the adamw launcher.
91	        const int64_t n = static_cast<int64_t>(p.numel());
92	        if (n == 0) continue;
93	        const unsigned blocks =
94	            static_cast<unsigned>(min<int64_t>(1024, (n + 255) / 256));
95	        dim3 grid(blocks), block(256);  // 4 wavefronts/block
96	        hipLaunchKernelGGL((native::grokfast_gfx942_kernel<float, float>), grid,
97	                           block, 0, 0,
98	                           p.data_ptr<float>(), m.data_ptr<float>(),
99	                           v.data_ptr<float>(), ema.data_ptr<float>(),
100	                           g.data_ptr<float>(),
101	                           gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd,
102	                           bc1, bc2, n);
103	        SG_HIP_LAUNCH_CHECK(0);  // mirror sm_90 SG_LAUNCH_CHECK after each launch
104	#else
105	        prim::ema_update_inplace(ema, g, gf_alpha);
106	        auto g_amp = g.to(torch::kFloat32) + gf_lamb * ema;
107	        prim::ema_update_inplace(m, g_amp, beta1);
108	        prim::ema_sq_update_inplace(v, g_amp, beta2);
109	        prim::adam_apply_inplace(p, m, v, lr, bc1, bc2, eps, wd);
110	#endif
111	    }
112	}
