122	void launch_fused_grokfast_adam(
123	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
124	    torch::Tensor ema, torch::Tensor grad,
125	    float alpha, float lamb, float beta1, float beta2,
126	    float lr, float weight_decay, float eps, float bc1, float bc2
127	) {
128	    std::vector<torch::Tensor> vp{param}, vea{exp_avg}, veas{exp_avg_sq},
129	                               vema{ema}, vg{grad};
130	    launch_grokfast_step(vp, vea, veas, vema, vg,
131	                         alpha, lamb, lr, beta1, beta2, eps, weight_decay,
132	                         bc1, bc2);
133	}
