147	// Under `#if defined(__HIPCC__)`, launch_grokfast_step() DISPATCHES the §5
148	// kernel per tensor (above) instead of the chain of ATen ema + amplify + adam:
149	//   dim3 grid(min(1024,(n+255)/256)), block(256);   // 4 wavefronts/block
150	//   hipLaunchKernelGGL((native::grokfast_gfx942_kernel<float,float>), grid,
151	//                      block, 0, 0, p_ptr, m_ptr, v_ptr, ema_ptr, g_ptr,
152	//                      gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd, bc1, bc2, n);
153	// The `#else` branch is the ATen CPU-host fallback (numerics-correct).
154	// 🟡 The hipcc host-launch compiles ONLY under hipcc (no hipcc in this env, so
155	// the hipLaunchKernelGGL glue is unverified here). The §5 device kernel itself
156	// is COMPILER-VERIFIED for gfx942 via scripts/amdgcn_check.sh (AMDGCN_OK).
157	#endif  // !defined(__AMDGCN__)  — end host orchestration (A)
158	
159	// ════════════════════════════════════════════════════════════════════════════
160	// (B) DEVICE pass — real hand-written AMDGCN grid-stride update (§5).
161	// Compiled by the AMDGCN device pass only: the Stage-5 gate (__AMDGCN__, no
162	// hipcc) AND the hipcc device pass (__HIPCC__). The host `.hip.cpp` TU never
163	// sees it — that pass keeps the ATen orchestration above (which LAUNCHES this
164	// kernel via hipLaunchKernelGGL, see §5.LAUNCH).
165	// ════════════════════════════════════════════════════════════════════════════
166	#if defined(__AMDGCN__) || defined(__HIPCC__) || defined(GROK_HIP_DEVICE)
167	#include "csrc/backends/hip/gfx942/amdgcn_primitives.hip.hpp"
168	// ── gate-only launch-builtin shim (verbatim from the adamw/looksam/mamba3 exemplar)
169	// The free-standing AMDGCN device gate stubs out <hip/hip_runtime.h>, so the
170	// launch builtins (threadIdx/blockIdx/blockDim/gridDim, __global__) HIP normally
171	// provides are absent. Model them with the AMDGCN workitem ISA builtins so the
172	// device bodies type-check. Active ONLY on the bare gate.
173	#if defined(__AMDGCN__) && !defined(__HIPCC__)
174	#ifndef GROK_GFX942_LAUNCH_SHIM_
175	#define GROK_GFX942_LAUNCH_SHIM_
176	struct GrokTidX { __device__ operator unsigned() const { return __builtin_amdgcn_workitem_id_x(); } };
177	struct GrokBidX { __device__ operator unsigned() const { return __builtin_amdgcn_workgroup_id_x(); } };
178	struct GrokBdimX{ __device__ operator unsigned() const { return __builtin_amdgcn_workgroup_size_x(); } };
179	struct GrokGdimX{ __device__ operator unsigned() const { return __builtin_amdgcn_grid_size_x()
180	                                                              / __builtin_amdgcn_workgroup_size_x(); } };
181	struct GrokThreadIdx { GrokTidX  x; };
182	struct GrokBlockIdx  { GrokBidX  x; };
183	struct GrokBlockDim  { GrokBdimX x; };
184	struct GrokGridDim   { GrokGdimX x; };
185	static GrokThreadIdx threadIdx;
186	static GrokBlockIdx  blockIdx;
187	static GrokBlockDim  blockDim;
188	static GrokGridDim   gridDim;
189	#ifndef __global__
190	#define __global__ __attribute__((amdgpu_kernel))
191	#endif
192	#endif  // GROK_GFX942_LAUNCH_SHIM_
193	#endif  // bare gate
194	// ============================================================================
195	// §5  AMD-NATIVE device kernel (Stage 5 hand-written AMDGCN).
196	//
197	// Grid-stride Grokfast: each workitem owns a stride of elements, reads grad
198	// read-once via amd::streaming_load (nontemporal — bypasses L2 for one-touch
199	// data, §2.7), fuses the slow-gradient EMA filter + amplification (g_amp =
200	// g + lamb*ema), the m/v Adam EMAs, and the bias-corrected decoupled-weight-
201	// decay apply in registers, then writes the param back via amd::streaming_store.
202	// The math is identical to sg::algorithms::grokfast_fused_step (bc1/bc2
203	// un-inverted → divide; sqrtf→__builtin_sqrtf under the bare gate).
204	//
205	// VECTORIZATION (WS5/A — scalar→f32x4): the fp32 path is bandwidth-bound, so the
206	// bulk loop is widened to WAVE-64 / 128-bit (dwordx4) memory access. Each
207	// iteration processes 4 contiguous floats as one amd::f32x4 via the templated
208	// amd::streaming_load<f32x4> (read-once grad) + amd::streaming_store<f32x4>
209	// (write-once param); the exp_avg / exp_avg_sq / ema state buffers are likewise
210	// vector-loaded/stored. The 4 lanes each evaluate the IDENTICAL scalar Grokfast
211	// expressions (no cross-lane mixing), so the result is BIT-IDENTICAL to the
212	// scalar kernel — only the access width changed. A scalar TAIL handles the
213	// final N%4 elements (and the whole array on the unaligned/sub-vector
214	// fallback). NO DPP is needed: Grokfast is purely elementwise (EMA filter +
215	// Adam) — there is no cross-lane reduction, so the butterfly primitives are
216	// unused.
217	// ============================================================================
218	namespace sg { namespace gfx942 { namespace native {
219	
220	namespace amd = ::sg::gfx942::amdgcn;
221	
222	// Stage-1 NaN/Inf gradient sanitization (mirror of sm_90 sg_sanitize_grad).
223	// Identity unless built with -DSG_SANITIZE_NONFINITE=1; default byte-identical.
224	#ifndef SG_SANITIZE_NONFINITE
225	#define SG_SANITIZE_NONFINITE 0
226	#endif
227	__device__ __forceinline__ float sg_sanitize_grad(float g) {
228	#if SG_SANITIZE_NONFINITE
229	    return __builtin_isfinite(g) ? g : 0.0f;
230	#else
231	    return g;
232	#endif
233	}
234	
235	// Per-element Grokfast apply — the canonical scalar body, shared by the scalar
236	// tail and (replicated lane-by-lane) the f32x4 fast-path so both are identical.
237	template <typename ParamT, typename GradT>
238	__device__ __forceinline__ void grokfast_apply_elem(
239	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
240	    float* __restrict__ exp_avg_sq, float* __restrict__ ema,
241	    const GradT* __restrict__ grad, int64_t i,
242	    float gf_alpha, float gf_lamb,
243	    float lr, float beta1, float beta2, float eps, float wd,
244	    float bc1, float bc2)
245	{
246	    const float g = sg_sanitize_grad(static_cast<float>(amd::streaming_load(&grad[i])));
247	    const float p = static_cast<float>(param[i]);
248	
249	    const float e_new = gf_alpha * ema[i] + (1.0f - gf_alpha) * g;
250	    ema[i] = e_new;
251	    const float g_amp = g + gf_lamb * e_new;
252	
253	    const float m = beta1 * exp_avg[i]    + (1.0f - beta1) * g_amp;
254	    const float v = beta2 * exp_avg_sq[i] + (1.0f - beta2) * g_amp * g_amp;
255	    exp_avg[i]    = m;
256	    exp_avg_sq[i] = v;
257	
258	    const float update = (m / bc1) / (__builtin_sqrtf(v / bc2) + eps);
259	    amd::streaming_store(&param[i],
260	                         static_cast<ParamT>(p - lr * (update + wd * p)));
261	}
262	
263	template <typename ParamT, typename GradT>
264	SG_KERNEL_BOUNDS(256, 8) void grokfast_gfx942_kernel(
265	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
266	    float* __restrict__ exp_avg_sq, float* __restrict__ ema,
267	    const GradT* __restrict__ grad,
268	    float gf_alpha, float gf_lamb,
269	    float lr, float beta1, float beta2, float eps, float wd,
270	    float bc1, float bc2, int64_t N)
271	{
272	    // 64-bit grid-stride indexing (Stage 1): cast BEFORE the multiply so a
273	    // launch covering >2^31 elements cannot wrap the 32-bit product.
274	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
275	    const int64_t tid    = static_cast<int64_t>(blockIdx.x) * blockDim.x
276	                       + threadIdx.x;
277	
278	    // VECTORIZED fast-path: only when param/grad are plain fp32 (the sole
279	    // instantiation); the constexpr guard lets any future bf16/fp16 combo fall
280	    // back cleanly to the scalar loop.
281	    constexpr bool kVecOk =
282	        sizeof(ParamT) == sizeof(float) && sizeof(GradT) == sizeof(float);
283	    const int64_t n4 = kVecOk ? (N >> 2) : 0;   // number of full float4 groups
284	
285	    using f32x4 = amd::f32x4;
286	    auto* p4  = reinterpret_cast<f32x4*>(param);
287	    auto* m4  = reinterpret_cast<f32x4*>(exp_avg);
288	    auto* v4  = reinterpret_cast<f32x4*>(exp_avg_sq);
289	    auto* e4  = reinterpret_cast<f32x4*>(ema);
290	    const auto* g4 = reinterpret_cast<const f32x4*>(grad);
291	
292	    for (int64_t q = tid; q < n4; q += stride) {
293	        const f32x4 g = amd::streaming_load(&g4[q]);   // 128-bit dwordx4 load
294	        const f32x4 p = p4[q];
295	        const f32x4 ea = m4[q];
296	        const f32x4 ev = v4[q];
297	        const f32x4 em = e4[q];
298	        f32x4 po, mo, vo, eo;
299	        // 4 lanes, each evaluating the IDENTICAL scalar Grokfast expressions.
300	        for (int l = 0; l < 4; ++l) {
301	            const float gl = sg_sanitize_grad(g[l]);  // identity unless sanitize on
302	            const float e_new = gf_alpha * em[l] + (1.0f - gf_alpha) * gl;
303	            eo[l] = e_new;
304	            const float g_amp = gl + gf_lamb * e_new;
305	            const float m = beta1 * ea[l] + (1.0f - beta1) * g_amp;
306	            const float v = beta2 * ev[l] + (1.0f - beta2) * g_amp * g_amp;
307	            mo[l] = m;
308	            vo[l] = v;
309	            const float update = (m / bc1) / (__builtin_sqrtf(v / bc2) + eps);
310	            po[l] = p[l] - lr * (update + wd * p[l]);
311	        }
312	        e4[q] = eo;
313	        m4[q] = mo;
314	        v4[q] = vo;
315	        amd::streaming_store(&p4[q], po);              // 128-bit dwordx4 store
316	    }
317	
318	    // SCALAR TAIL: the final N%4 elements (and the whole array when kVecOk is
319	    // false / N<4). Grid-strided over the remaining indices.
320	    for (int64_t i = (n4 << 2) + tid; i < N; i += stride) {
321	        grokfast_apply_elem(param, exp_avg, exp_avg_sq, ema, grad, i,
322	                            gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd,
323	                            bc1, bc2);
324	    }
325	}
326	
327	// Force-instantiate the grokking dtype combo (fp32 param + fp32 grad) so the
328	// device pass emits the kernel; the host TU dispatches on dtype.
329	template __global__ void grokfast_gfx942_kernel<float, float>(
330	    float*, float*, float*, float*, const float*, float, float, float, float,
331	    float, float, float, float, float, int64_t);
332	
333	}}} // namespace sg::gfx942::native
334	#endif  // (B) device pass
