31	// HIP gfx942 launch glue for LookSAM.
32	// Algorithm: csrc/algorithms/looksam.h
33	//
34	// COMPUTE PATTERN
35	// Four separate ops (matches the algorithm-header structure):
36	//   1. perturb:     p_pert = p + rho * (g / ||g||)              — elementwise + 1 reduction
37	//   2. restore:     p = p_pert - rho * (g / ||g||)              — elementwise
38	//   3. set_direction: sam_dir = g_sam - g                       — elementwise
39	//   4. apply:       g_adj = (1-alpha)*g + alpha*sam_dir; AdamW(g_adj)
40	// The ||g|| computation in steps 1 + 2 is a global reduction.
41	//
42	// MFMA APPLICABILITY: none. Elementwise + scalar reduction.
43	//
44	// WHY ATEN HERE
45	// Each op is a chain of broadcasted tensor expressions. ATen + rocPRIM
46	// handles the elementwise + reduction patterns natively. Hand-written
47	// fusion would chain perturb + reduce + apply into 1 kernel instead of 3;
48	// gain is ≈ 1.7× and needs hardware verification.
49	
