84	
85	void launch_looksam_perturb(
86	    std::vector<torch::Tensor>& params,
87	    std::vector<torch::Tensor>& backups,
88	    std::vector<torch::Tensor>& grads,
89	    float scale
90	) {
91	    for (size_t i = 0; i < params.size(); i++) {
92	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
93	        backups[i].copy_(params[i]);
94	        params[i].add_(grads[i].to(params[i].scalar_type()), scale);
95	    }
96	}
97	
98	void launch_looksam_restore(
99	    std::vector<torch::Tensor>& params,
100	    std::vector<torch::Tensor>& backups
101	) {
102	    for (size_t i = 0; i < params.size(); i++) {
103	        params[i].copy_(backups[i]);
104	    }
105	}
106	
107	void launch_looksam_set_direction(
108	    std::vector<torch::Tensor>& sam_dirs,
109	    std::vector<torch::Tensor>& grads_sam,
110	    std::vector<torch::Tensor>& grads_orig
111	) {
112	    for (size_t i = 0; i < sam_dirs.size(); i++) {
113	        sam_dirs[i].copy_(grads_sam[i] - grads_orig[i]);
114	    }
115	}
116	
117	void launch_looksam_apply(
118	    std::vector<torch::Tensor>& params,
119	    std::vector<torch::Tensor>& exp_avgs,
120	    std::vector<torch::Tensor>& exp_avg_sqs,
121	    std::vector<torch::Tensor>& sam_dirs,
122	    std::vector<torch::Tensor>& grads,
123	    float alpha,
124	    float lr, float beta1, float beta2, float eps, float wd,
125	    float bc1, float bc2
126	) {
127	    for (size_t i = 0; i < params.size(); i++) {
128	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
129	        auto& p = params[i];
130	        auto& g = grads[i];
131	        auto& m = exp_avgs[i];
132	        auto& v = exp_avg_sqs[i];
133	
134	        auto g_adj = (1.0f - alpha) * g.to(torch::kFloat32) + alpha * sam_dirs[i];
135	        prim::ema_update_inplace(m, g_adj, beta1);
136	        prim::ema_sq_update_inplace(v, g_adj, beta2);
137	        prim::adam_apply_inplace(p, m, v, lr, bc1, bc2, eps, wd);
138	    }
139	}
