141	
142	void launch_looksam_direction_adjust_fused(
143	    torch::Tensor grad, torch::Tensor sam_grad, torch::Tensor v_dir, float inv_norm, float lambda, float grad_norm
144	) {
145	    // grad = (1 - lambda) * grad + lambda * grad_norm * (v_dir * inv_norm)
146	    auto scaled_dir = v_dir * (inv_norm * grad_norm);
147	    grad.mul_(1.0f - lambda).add_(scaled_dir, lambda);
148	}
