150	void launch_looksam_norm_reduce(
151	    torch::Tensor grad, torch::Tensor sam_grad, torch::Tensor results /* [diff_norm, grad_norm] */
152	) {
153	    // results[0] = ||sam_grad - grad||, results[1] = ||grad||
154	#if defined(__HIPCC__)
155	    // LIVE (hipcc): dispatch the §5 DPP sum-of-squares reduction kernel for each
156	    // norm, matching the ATen body's two .norm() stages. ‖x‖ = sqrt(Σ x²): one
157	    // reduce per quantity into a single-float AGENT accumulator, host does sqrt.
158	    //   STAGE 1: ‖sam_grad − grad‖ — reduce the diff buffer; STAGE 2: ‖grad‖.
159	    // §5.LAUNCH grid/block: block(256) = 4 wavefronts, grid = min(1024,(n+255)/256).
160	    auto diff = (sam_grad.to(torch::kFloat32) - grad.to(torch::kFloat32)).contiguous();
161	    auto gf   = grad.to(torch::kFloat32).contiguous();
162	    // 64-bit safe element counts + grid sizing (Stage 1): numel can exceed 2^31.
163	    const int64_t n_diff = static_cast<int64_t>(diff.numel());
164	    const int64_t n_grad = static_cast<int64_t>(gf.numel());
165	
166	    auto acc_opts = torch::TensorOptions().device(grad.device()).dtype(torch::kFloat32);
167	    auto acc = torch::zeros({2}, acc_opts);  // [Σ diff², Σ grad²]
168	    auto stream = at::hip::getCurrentHIPStream();
169	
170	    if (n_diff > 0) {
171	        dim3 block(256), grid(static_cast<unsigned>(
172	            std::min<int64_t>(1024, (n_diff + 255) / 256)));
173	        hipLaunchKernelGGL(native::looksam_gfx942_sumsq_reduce, grid, block, 0, stream,
174	                           diff.data_ptr<float>(), acc.data_ptr<float>(), n_diff);
175	        SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
176	    }
177	    if (n_grad > 0) {
178	        dim3 block(256), grid(static_cast<unsigned>(
179	            std::min<int64_t>(1024, (n_grad + 255) / 256)));
180	        hipLaunchKernelGGL(native::looksam_gfx942_sumsq_reduce, grid, block, 0, stream,
181	                           gf.data_ptr<float>(), acc.data_ptr<float>() + 1, n_grad);
182	        SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
183	    }
184	    auto norms = acc.sqrt();  // [‖diff‖, ‖grad‖]
185	    results[0] = norms[0];
186	    results[1] = norms[1];
187	#else
188	    auto diff = sam_grad.to(torch::kFloat32) - grad.to(torch::kFloat32);
189	    results[0] = diff.norm();
190	    results[1] = grad.to(torch::kFloat32).norm();
191	#endif
192	}
