250	// §5  AMD-NATIVE device kernel (Stage 5 hand-written AMDGCN).
251	//
252	// The SAM gradient L2 norm ‖g‖ = sqrt(Σ_i g_i²). The high-value AMDGCN piece is
253	// the global sum-of-squares reduction; the host does the final sqrt/rsqrt (the
254	// 1/‖g‖ perturbation scale). This is the canonical 2-level (wave→block→grid)
255	// tree from the task spec:
256	//   1. each thread grid-strides g², accumulating a per-thread partial;
257	//   2. amd::wave_reduce_add_dpp gives every lane the per-wavefront sum (§2.6);
258	//   3. lane 0 of each wavefront writes its sum to an LDS slot; workgroup_barrier;
259	//   4. the first wavefront reduces the LDS slots via a second DPP reduce;
260	//   5. one thread does amd::atomic_add_agent_f32 to the global accumulator
261	//      (§2.13: AMD has no DSMEM, so cross-workgroup uses an AGENT-scope atomic
262	//      visible across all 8 XCDs of MI300X).
263	// APPLY: the per-element perturb/restore/AdamW apply stays on the ATen host path
264	// (launch_looksam_*) — only the norm reduction is migrated to AMDGCN.
265	// ============================================================================
266	namespace sg { namespace gfx942 { namespace native {
267	
268	namespace amd = ::sg::gfx942::amdgcn;
269	static constexpr int kWave = 64;   // == amd::kWave (CDNA3 wavefront width)
270	
271	// Stage-1 NaN/Inf gradient sanitization (mirror of sm_90 sg_sanitize_grad).
272	// Identity unless built with -DSG_SANITIZE_NONFINITE=1; default byte-identical.
273	#ifndef SG_SANITIZE_NONFINITE
274	#define SG_SANITIZE_NONFINITE 0
275	#endif
276	__device__ __forceinline__ float sg_sanitize_grad(float g) {
277	#if SG_SANITIZE_NONFINITE
278	    return __builtin_isfinite(g) ? g : 0.0f;
279	#else
280	    return g;
281	#endif
282	}
283	
284	// Block (workgroup) sum-of-squares of `g[0..n)`, atomically added to *acc.
285	// blockDim.x must be a multiple of kWave and <= kWave*kWave (<= 4096); LDS holds
286	// one float per wavefront (<= 64 floats).
287	__device__ __forceinline__ void looksam_sumsq_block(
288	    const float* __restrict__ g, float* __restrict__ acc, int64_t n)
289	{
290	    // LDS/lane bookkeeping is LOCAL to the block (<= 4096 threads) → int. Only
291	    // the GLOBAL element index/stride (gtid/stride/i) is int64 so the per-element
292	    // reduction loop cannot wrap at 2^31 (Stage 1).
293	    const int tid    = static_cast<int>(threadIdx.x);
294	    const int lane   = tid % kWave;
295	    const int waveId = tid / kWave;
296	    const int wpb    = static_cast<int>(blockDim.x) / kWave;
297	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x + tid;
298	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
299	
300	    float local = 0.f;
301	    for (int64_t i = gtid; i < n; i += stride) {
302	        float v = amd::streaming_load(&g[i]);
303	        local += v * v;
304	    }
305	    // wavefront DPP reduce: every lane holds the wavefront sum.
306	    local = amd::wave_reduce_add_dpp(local);
307	
308	    __shared__ float lds[kWave];
309	    if (lane == 0) lds[waveId] = local;
310	    amd::workgroup_barrier_release();
311	
312	    // first wavefront reduces the per-wavefront slots, then one AGENT atomic.
313	    if (waveId == 0) {
314	        float slot = (lane < wpb) ? lds[lane] : 0.f;
315	        slot = amd::wave_reduce_add_dpp(slot);
316	        if (lane == 0) amd::atomic_add_agent_f32(acc, slot);
317	    }
318	}
319	
320	// Bandwidth-bound reduction → high occupancy (256-thread block = 4 wavefronts;
321	// 8 waves/EU) to hide global-memory latency. (WS5 occupancy wire.)
322	extern "C" SG_KERNEL_BOUNDS(256, 8) void looksam_gfx942_sumsq_reduce(
323	    const float* __restrict__ g, float* __restrict__ acc, int64_t n)
324	{
325	    looksam_sumsq_block(g, acc, n);
326	}
327	
328	// ════════════════════════════════════════════════════════════════════════════
329	// §5.2  LookSAM APPLY — per-element param/state update (elementwise, vectorized
330	// only; NO DPP — the cross-lane ‖g‖/‖diff‖ reduction is §5 above and stays as-is).
331	//
332	// Once the reduction/scale is known, the apply forms the SAM-adjusted gradient
333	//   g_adj = (1 - alpha)·g + alpha·sam_dir
334	// then runs the AdamW EMAs + bias-corrected decoupled-weight-decay apply:
335	//   m = beta1·m + (1-beta1)·g_adj ;  v = beta2·v + (1-beta2)·g_adj²
336	//   update = (m/bc1)/(sqrt(v/bc2)+eps) ;  p = p - lr·(update + wd·p)
337	// Math is verbatim from launch_looksam_apply()'s ATen body (bc1/bc2 un-inverted
338	// → divide; sqrtf→__builtin_sqrtf).
339	//
340	// VECTORIZATION (WS5/B — scalar→f32x4): the fp32 path is bandwidth-bound, so the
341	// bulk loop is widened to 128-bit (dwordx4) memory access. grad and sam_dir are
342	// read-once via amd::streaming_load<f32x4>; exp_avg / exp_avg_sq are vector
343	// load/stored; the param write-once goes through amd::streaming_store<f32x4>.
344	// The 4 lanes each evaluate the IDENTICAL scalar expressions (uniform scalars
345	// alpha/lr/beta1/beta2/bc1/bc2/eps/wd applied to all lanes), so the result is
346	// BIT-IDENTICAL to the scalar path — only the access width changes. A scalar
347	// TAIL handles the final N%4 (and the whole array on the fp32-only fallback).
348	// ════════════════════════════════════════════════════════════════════════════
349	
350	// Per-element LookSAM apply — canonical scalar body, shared by the scalar tail
351	// and (replicated lane-by-lane) the f32x4 fast-path so both are bit-identical.
352	template <typename ParamT, typename GradT>
353	__device__ __forceinline__ void looksam_apply_elem(
354	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
355	    float* __restrict__ exp_avg_sq, const float* __restrict__ sam_dir,
356	    const GradT* __restrict__ grad, int64_t i, float alpha,
357	    float lr, float beta1, float beta2, float eps, float wd, float bc1, float bc2)
358	{
359	    const float g     = sg_sanitize_grad(static_cast<float>(amd::streaming_load(&grad[i])));
360	    const float sd    = amd::streaming_load(&sam_dir[i]);
361	    const float p     = static_cast<float>(param[i]);
362	    const float g_adj = (1.0f - alpha) * g + alpha * sd;
363	    const float m     = beta1 * exp_avg[i]    + (1.0f - beta1) * g_adj;
364	    const float v     = beta2 * exp_avg_sq[i] + (1.0f - beta2) * g_adj * g_adj;
365	    exp_avg[i]    = m;
366	    exp_avg_sq[i] = v;
367	    const float update = (m / bc1) / (__builtin_sqrtf(v / bc2) + eps);
368	    amd::streaming_store(&param[i],
369	                         static_cast<ParamT>(p - lr * (update + wd * p)));
370	}
371	
372	template <typename ParamT, typename GradT>
373	SG_KERNEL_BOUNDS(256, 8) void looksam_gfx942_apply_kernel(
374	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
375	    float* __restrict__ exp_avg_sq, const float* __restrict__ sam_dir,
376	    const GradT* __restrict__ grad, float alpha,
377	    float lr, float beta1, float beta2, float eps, float wd,
378	    float bc1, float bc2, int64_t N)
379	{
380	    // 64-bit grid-stride indexing (Stage 1): cast BEFORE the multiply.
381	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
382	    const int64_t tid    = static_cast<int64_t>(blockIdx.x) * blockDim.x
383	                       + threadIdx.x;
384	
385	    constexpr bool kVecOk =
386	        sizeof(ParamT) == sizeof(float) && sizeof(GradT) == sizeof(float);
387	    const int64_t n4 = kVecOk ? (N >> 2) : 0;   // number of full float4 groups
388	
389	    using f32x4 = amd::f32x4;
390	    auto* p4 = reinterpret_cast<f32x4*>(param);
391	    auto* m4 = reinterpret_cast<f32x4*>(exp_avg);
392	    auto* v4 = reinterpret_cast<f32x4*>(exp_avg_sq);
393	    const auto* g4  = reinterpret_cast<const f32x4*>(grad);
394	    const auto* sd4 = reinterpret_cast<const f32x4*>(sam_dir);
395	
396	    for (int64_t q = tid; q < n4; q += stride) {
397	        const f32x4 g  = amd::streaming_load(&g4[q]);   // 128-bit dwordx4 load
398	        const f32x4 sd = amd::streaming_load(&sd4[q]);  // sam_dir vector-loaded
399	        const f32x4 p  = p4[q];
400	        const f32x4 ea = m4[q];
401	        const f32x4 ev = v4[q];
402	        f32x4 mo, vo, po;
403	        for (int l = 0; l < 4; ++l) {
404	            const float gl = sg_sanitize_grad(g[l]);  // identity unless sanitize on
405	            const float g_adj = (1.0f - alpha) * gl + alpha * sd[l];
406	            const float m = beta1 * ea[l] + (1.0f - beta1) * g_adj;
407	            const float v = beta2 * ev[l] + (1.0f - beta2) * g_adj * g_adj;
408	            mo[l] = m;
409	            vo[l] = v;
410	            const float update = (m / bc1) / (__builtin_sqrtf(v / bc2) + eps);
411	            po[l] = p[l] - lr * (update + wd * p[l]);
412	        }
413	        m4[q] = mo;
414	        v4[q] = vo;
415	        amd::streaming_store(&p4[q], po);               // 128-bit dwordx4 store
416	    }
417	
418	    // SCALAR TAIL: the final N%4 elements (and the whole array on fp32 fallback).
419	    for (int64_t i = (n4 << 2) + tid; i < N; i += stride) {
420	        looksam_apply_elem(param, exp_avg, exp_avg_sq, sam_dir, grad, i, alpha,
421	                           lr, beta1, beta2, eps, wd, bc1, bc2);
422	    }
423	}
