201	// Canonical persistent-EMA Prodigy estimator (mirrors the sm_90 launcher):
202	// r_num_buf / s_den_buf are running EMAs that PERSIST across steps, decayed by
203	// beta3 = sqrt(beta2) here (NOT zeroed) before this step's r/s reduction is
204	// added on top, so d = max(d_prev, d_coef·r_ema/|s_ema|) PLATEAUS once params
205	// stop drifting from init (the instantaneous form ratcheted d up without bound
206	// and collapsed training). prodigy.h device math is UNCHANGED — the EMA/beta3/
207	// d_coef live in this host launcher.
208	void launch_multi_tensor_prodigy_fused_reduce_step(
209	    std::vector<torch::Tensor>& params, std::vector<torch::Tensor>& grads, std::vector<torch::Tensor>& param_inits, std::vector<torch::Tensor>& exp_avgs, std::vector<torch::Tensor>& exp_avg_sqs, std::vector<torch::Tensor>& s_bufs, std::vector<float>& bc1s, std::vector<float>& bc2s, torch::Tensor d_lr_buf, torch::Tensor r_num_buf, torch::Tensor s_den_buf, float beta1, float beta2, float beta3, float lr, float wd, float eps, float d_coef
210	) {
211	    if (params.empty()) return;
212	    auto dev = params[0].device();
213	    float d_prev = d_lr_buf.item<float>();
214	
215	    // Phase 1: PERSISTENT-EMA accumulate. Seed r/s with the beta3-decayed EMAs
216	    // carried in from the host, then add this step's per-tensor reduction.
217	    auto r_sum = (r_num_buf.to(torch::kFloat32) * beta3).reshape({});
218	    auto s_sum = (s_den_buf.to(torch::kFloat32) * beta3).reshape({});
219	#if defined(__HIPCC__)
220	    // LIVE (hipcc): §5 DPP r/s reduction, one launch per tensor → 2-float AGENT
221	    // accumulator [r,s]. d_prev² / d_prev² folded in the kernel; identical to ATen.
222	    auto rs_acc = torch::zeros({2}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
223	    auto stream = at::hip::getCurrentHIPStream();
224	    for (size_t i = 0; i < params.size(); i++) {
225	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
226	        auto gf = grads[i].to(torch::kFloat32).contiguous();
227	        auto pf = params[i].to(torch::kFloat32).contiguous();
228	        auto pif = param_inits[i].to(torch::kFloat32).contiguous();
229	        // 64-bit safe element count + grid sizing (Stage 1).
230	        const int64_t n = static_cast<int64_t>(gf.numel());
231	        dim3 block(256), grid(static_cast<unsigned>(
232	            std::min<int64_t>(1024, (n + 255) / 256)));
233	        hipLaunchKernelGGL(native::prodigy_gfx942_rs_reduce, grid, block, 0, stream,
234	                           gf.data_ptr<float>(), pf.data_ptr<float>(),
235	                           pif.data_ptr<float>(),
236	                           rs_acc.data_ptr<float>(), rs_acc.data_ptr<float>() + 1,
237	                           d_prev, n);
238	        SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
239	    }
240	    r_sum += rs_acc[0];
241	    s_sum += rs_acc[1];
242	#else
243	    for (size_t i = 0; i < params.size(); i++) {
244	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
245	        auto gf = grads[i].to(torch::kFloat32);
246	        auto delta = (param_inits[i] - params[i]).to(torch::kFloat32);
247	        r_sum += (gf * delta).sum() * (d_prev * d_prev);
248	        s_sum += gf.abs().sum() * (d_prev * d_prev);
249	    }
250	#endif
251	
252	    // Persist the UNSCALED EMA numerator/denominator back to the host scalars
253	    // (d_coef is applied only to the candidate, not the stored EMA).
254	    r_num_buf.copy_(r_sum.reshape({1}));
255	    s_den_buf.copy_(s_sum.reshape({1}));
256	
257	    // Phase 2: update d = max(d_prev, d_coef·r_ema/|s_ema|).
258	    auto candidate = (d_coef * r_sum) / (s_sum.abs() + 1e-12f);
259	    d_lr_buf.copy_(torch::maximum(d_lr_buf.new_full({}, d_prev), candidate));
260	    float d_val = d_lr_buf.item<float>();
261	
262	    // Phase 3: apply Adam with d as effective lr
263	    for (size_t i = 0; i < params.size(); i++) {
264	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
265	        auto gf = d_val * grads[i].to(torch::kFloat32);
266	        prim::ema_update_inplace(exp_avgs[i], gf, beta1);
267	        prim::ema_sq_update_inplace(exp_avg_sqs[i], gf, beta2);
268	        s_bufs[i].add_(grads[i].to(torch::kFloat32), d_val);
269	        prim::adam_apply_inplace(params[i], exp_avgs[i], exp_avg_sqs[i],
270	                                 d_val, bc1s[i], bc2s[i], eps, wd);
271	    }
272	}
