332	// §5  AMD-NATIVE device kernel (Stage 5 hand-written AMDGCN).
333	//
334	// The prodigy_reduce step: TWO parallel global sums computed in one pass,
335	// mirroring the sm_90 prodigy_reduce_kernel —
336	//   r_global = Σ_i g_i · (p_init_i − p_i) · d_prev²    (numerator)
337	//   s_global = Σ_i d_prev² · |g_i|                       (|denominator|)
338	// then on the host: d_new = max(d_prev, r_global / (|s_global| + 1e-12)).
339	// Each thread accumulates BOTH partials, then we run TWO independent
340	// wave→block→AGENT-atomic trees (the standard 2-level tree from the spec):
341	//   1. each thread grid-strides, accumulating r_local and s_local;
342	//   2. amd::wave_reduce_add_dpp on each → per-wavefront r/s sums (§2.6);
343	//   3. lane 0 of each wavefront writes r/s to LDS slots; workgroup_barrier;
344	//   4. the first wavefront reduces both slot arrays via a second DPP reduce;
345	//   5. one thread does two amd::atomic_add_agent_f32 (to r_acc and s_acc)
346	//      (§2.13: AGENT-scope atomics, visible across all 8 XCDs of MI300X).
347	// APPLY: the per-element Adam apply (with d as the effective lr) stays on the
348	// ATen host path (launch_prodigy_step) — only the r/s reduction is AMDGCN.
349	// ============================================================================
350	namespace sg { namespace gfx942 { namespace native {
351	
352	namespace amd = ::sg::gfx942::amdgcn;
353	
354	// Stage-1 NaN/Inf gradient sanitization (mirror of sm_90 sg_sanitize_grad).
355	// Identity unless built with -DSG_SANITIZE_NONFINITE=1; default byte-identical.
356	// Applied on the APPLY path's grad read only (the r/s reduction is unchanged).
357	#ifndef SG_SANITIZE_NONFINITE
358	#define SG_SANITIZE_NONFINITE 0
359	#endif
360	__device__ __forceinline__ float sg_sanitize_grad(float g) {
361	#if SG_SANITIZE_NONFINITE
362	    return __builtin_isfinite(g) ? g : 0.0f;
363	#else
364	    return g;
365	#endif
366	}
367	static constexpr int kWave = 64;   // == amd::kWave (CDNA3 wavefront width)
368	
369	__device__ __forceinline__ float dabsf(float x) { return __builtin_fabsf(x); }
370	
371	// Block (workgroup) prodigy r/s reduction over `[0..n)`, two AGENT atomics.
372	// r_i = g_i·(p_init_i − p_i)·d_prev² ;  s_i = d_prev²·|g_i|.
373	// blockDim.x must be a multiple of kWave and <= kWave*kWave (<= 4096); LDS holds
374	// one float per wavefront per quantity (<= 2*64 floats).
375	__device__ __forceinline__ void prodigy_rs_block(
376	    const float* __restrict__ g, const float* __restrict__ p,
377	    const float* __restrict__ p_init, float* __restrict__ r_acc,
378	    float* __restrict__ s_acc, float d_prev, int64_t n)
379	{
380	    // LDS/lane bookkeeping is LOCAL to the block (<= 4096 threads) → int. The
381	    // GLOBAL element index/stride is int64 so the reduction cannot wrap (Stage 1).
382	    const int tid    = static_cast<int>(threadIdx.x);
383	    const int lane   = tid % kWave;
384	    const int waveId = tid / kWave;
385	    const int wpb    = static_cast<int>(blockDim.x) / kWave;
386	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x + tid;
387	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
388	    const float d2   = d_prev * d_prev;
389	
390	    // VECTORIZED reduction body (WS5/item 6): widen the 3-buffer read to 128-bit
391	    // (f32x4 / dwordx4) memory access — was three scalar loads/iter. The 4 lanes
392	    // accumulate the IDENTICAL scalar partials (r_i = g_i·(p_init_i−p_i)·d_prev²,
393	    // s_i = d²·|g_i|), so the per-thread partials are bit-identical to the scalar
394	    // form — only the access width changes. A scalar TAIL covers the n%4 remainder.
395	    // NONTEMPORAL POLICY: g is the read-once grad → streaming (nontemporal); p is
396	    // the current param (read here, written by the apply → recurring) and p_init
397	    // is re-read every step → both CACHED (keep L2-resident).
398	    using f32x4 = amd::f32x4;
399	    const int64_t n4v = n & ~static_cast<int64_t>(3);   // largest mult of 4 <= n
400	    const auto* g4  = reinterpret_cast<const f32x4*>(g);
401	    const auto* p4  = reinterpret_cast<const f32x4*>(p);
402	    const auto* pi4 = reinterpret_cast<const f32x4*>(p_init);
403	
404	    float r_local = 0.f, s_local = 0.f;
405	    for (int64_t q = gtid; q < (n4v >> 2); q += stride) {
406	        const f32x4 gv  = amd::streaming_load(&g4[q]);   // read-once grad
407	        const f32x4 pv  = amd::cached_load(&p4[q]);      // recurring param (cached)
408	        const f32x4 piv = amd::cached_load(&pi4[q]);     // p_init re-read (cached)
409	        #pragma unroll
410	        for (int l = 0; l < 4; ++l) {
411	            float delta = piv[l] - pv[l];
412	            r_local += gv[l] * delta * d2;
413	            s_local += d2 * dabsf(gv[l]);
414	        }
415	    }
416	    // SCALAR TAIL: the final n%4 elements, identical per-element partials.
417	    for (int64_t i = n4v + gtid; i < n; i += stride) {
418	        float gi = amd::streaming_load(&g[i]);
419	        float delta = amd::cached_load(&p_init[i]) - amd::cached_load(&p[i]);
420	        r_local += gi * delta * d2;
421	        s_local += d2 * dabsf(gi);
422	    }
423	    // two wavefront DPP reduces: every lane holds the wavefront r/s sums.
424	    r_local = amd::wave_reduce_add_dpp(r_local);
425	    s_local = amd::wave_reduce_add_dpp(s_local);
426	
427	    __shared__ float lds_r[kWave];
428	    __shared__ float lds_s[kWave];
429	    if (lane == 0) { lds_r[waveId] = r_local; lds_s[waveId] = s_local; }
430	    amd::workgroup_barrier_release();
431	
432	    // first wavefront reduces both per-wavefront slot arrays, then two atomics.
433	    if (waveId == 0) {
434	        float rs = (lane < wpb) ? lds_r[lane] : 0.f;
435	        float ss = (lane < wpb) ? lds_s[lane] : 0.f;
436	        rs = amd::wave_reduce_add_dpp(rs);
437	        ss = amd::wave_reduce_add_dpp(ss);
438	        if (lane == 0) {
439	            amd::atomic_add_agent_f32(r_acc, rs);
440	            amd::atomic_add_agent_f32(s_acc, ss);
441	        }
442	    }
443	}
