445	// Bandwidth-bound reduction → high occupancy (256-thread block = 4 wavefronts;
446	// 8 waves/EU) to hide global-memory latency. (WS5 occupancy wire.)
447	extern "C" SG_KERNEL_BOUNDS(256, 8) void prodigy_gfx942_rs_reduce(
448	    const float* __restrict__ g, const float* __restrict__ p,
449	    const float* __restrict__ p_init, float* __restrict__ r_acc,
450	    float* __restrict__ s_acc, float d_prev, int64_t n)
451	{
452	    prodigy_rs_block(g, p, p_init, r_acc, s_acc, d_prev, n);
453	}
454	
455	// ════════════════════════════════════════════════════════════════════════════
456	// §5.2  Prodigy APPLY — per-element param/state update (elementwise, vectorized
457	// only; NO DPP — the cross-lane r/s reduction is §5 above and stays as-is).
458	//
459	// Once the d-factor d_val = max(d_prev, r/(|s|+1e-12)) is known (host-reduced
460	// from the §5 r/s sums), the apply scales the gradient by d_val and runs the
461	// Adam EMAs + bias-corrected decoupled-weight-decay apply with d_val as the
462	// effective lr, plus the s-track accumulator:
463	//   g_s = d_val·g
464	//   m   = beta1·m + (1-beta1)·g_s ;  v = beta2·v + (1-beta2)·g_s²
465	//   st  = st + d_val·g
466	//   update = (m/bc1)/(sqrt(v/bc2)+eps) ;  p = p - d_val·(update + wd·p)
467	// Math is verbatim from launch_prodigy_step()'s ATen body (ema_update_inplace,
468	// ema_sq_update_inplace, s_track add_, adam_apply_inplace with lr=d_val;
469	// bc1/bc2 un-inverted → divide; sqrtf→__builtin_sqrtf).
470	//
471	// VECTORIZATION (WS5/B — scalar→f32x4): the fp32 path is bandwidth-bound, so the
472	// bulk loop is widened to 128-bit (dwordx4) memory access. grad is read-once via
473	// amd::streaming_load<f32x4>; exp_avg / exp_avg_sq / s_track are vector
474	// load/stored; the param write-once goes through amd::streaming_store<f32x4>.
475	// The 4 lanes each evaluate the IDENTICAL scalar expressions (uniform scalars
476	// d_val/beta1/beta2/bc1/bc2/eps/wd applied to all lanes), so the result is
477	// BIT-IDENTICAL to the scalar path — only the access width changes. A scalar
478	// TAIL handles the final N%4 (and the whole array on the fp32-only fallback).
479	// ════════════════════════════════════════════════════════════════════════════
480	
481	// Per-element Prodigy apply — canonical scalar body, shared by the scalar tail
482	// and (replicated lane-by-lane) the f32x4 fast-path so both are bit-identical.
483	template <typename ParamT, typename GradT>
484	__device__ __forceinline__ void prodigy_apply_elem(
485	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
486	    float* __restrict__ exp_avg_sq, float* __restrict__ s_track,
487	    const GradT* __restrict__ grad, int64_t i, float d_val,
488	    float beta1, float beta2, float eps, float wd, float bc1, float bc2)
489	{
490	    const float g   = sg_sanitize_grad(static_cast<float>(amd::streaming_load(&grad[i])));
491	    const float p   = static_cast<float>(param[i]);
492	    const float g_s = d_val * g;
493	    const float m   = beta1 * exp_avg[i]    + (1.0f - beta1) * g_s;
494	    const float v   = beta2 * exp_avg_sq[i] + (1.0f - beta2) * g_s * g_s;
495	    exp_avg[i]    = m;
496	    exp_avg_sq[i] = v;
497	    s_track[i]    = s_track[i] + d_val * g;
498	    const float update = (m / bc1) / (__builtin_sqrtf(v / bc2) + eps);
499	    amd::streaming_store(&param[i],
500	                         static_cast<ParamT>(p - d_val * (update + wd * p)));
501	}
502	
503	template <typename ParamT, typename GradT>
504	SG_KERNEL_BOUNDS(256, 8) void prodigy_gfx942_apply_kernel(
505	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
506	    float* __restrict__ exp_avg_sq, float* __restrict__ s_track,
507	    const GradT* __restrict__ grad, float d_val,
508	    float beta1, float beta2, float eps, float wd,
509	    float bc1, float bc2, int64_t N)
510	{
511	    // 64-bit grid-stride indexing (Stage 1): cast BEFORE the multiply.
512	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
513	    const int64_t tid    = static_cast<int64_t>(blockIdx.x) * blockDim.x
514	                       + threadIdx.x;
515	
516	    constexpr bool kVecOk =
517	        sizeof(ParamT) == sizeof(float) && sizeof(GradT) == sizeof(float);
518	    const int64_t n4 = kVecOk ? (N >> 2) : 0;   // number of full float4 groups
519	
520	    using f32x4 = amd::f32x4;
521	    auto* p4 = reinterpret_cast<f32x4*>(param);
522	    auto* m4 = reinterpret_cast<f32x4*>(exp_avg);
523	    auto* v4 = reinterpret_cast<f32x4*>(exp_avg_sq);
524	    auto* s4 = reinterpret_cast<f32x4*>(s_track);
525	    const auto* g4 = reinterpret_cast<const f32x4*>(grad);
526	
527	    for (int64_t q = tid; q < n4; q += stride) {
528	        const f32x4 g  = amd::streaming_load(&g4[q]);   // 128-bit dwordx4 load
529	        const f32x4 p  = p4[q];
530	        const f32x4 ea = m4[q];
531	        const f32x4 ev = v4[q];
532	        const f32x4 st = s4[q];
533	        f32x4 mo, vo, so, po;
534	        for (int l = 0; l < 4; ++l) {
535	            const float gl = sg_sanitize_grad(g[l]);  // identity unless sanitize on
536	            const float g_s = d_val * gl;
537	            const float m = beta1 * ea[l] + (1.0f - beta1) * g_s;
538	            const float v = beta2 * ev[l] + (1.0f - beta2) * g_s * g_s;
539	            mo[l] = m;
540	            vo[l] = v;
541	            so[l] = st[l] + d_val * gl;
542	            const float update = (m / bc1) / (__builtin_sqrtf(v / bc2) + eps);
543	            po[l] = p[l] - d_val * (update + wd * p[l]);
544	        }
545	        m4[q] = mo;
546	        v4[q] = vo;
547	        s4[q] = so;
548	        amd::streaming_store(&p4[q], po);               // 128-bit dwordx4 store
549	    }
550	
551	    // SCALAR TAIL: the final N%4 elements (and the whole array on fp32 fallback).
552	    for (int64_t i = (n4 << 2) + tid; i < N; i += stride) {
553	        prodigy_apply_elem(param, exp_avg, exp_avg_sq, s_track, grad, i, d_val,
554	                           beta1, beta2, eps, wd, bc1, bc2);
555	    }
556	}
