104	void launch_supergrok11_step(
105	    std::vector<torch::Tensor>& params,
106	    std::vector<torch::Tensor>& exp_avgs,
107	    std::vector<torch::Tensor>& exp_avg_sqs,
108	    std::vector<torch::Tensor>& mu_bufs,
109	    std::vector<torch::Tensor>& grads,
110	    std::vector<torch::Tensor>& sharpnesses,
111	    std::vector<torch::Tensor>& momenta,
112	    const torch::Tensor& phi_W1,
113	    const torch::Tensor& phi_b1,
114	    const torch::Tensor& phi_W2,
115	    float phi_b2,
116	    float alpha,
117	    float lr, float beta1, float beta2, float eps, float wd,
118	    float bc1, float bc2,
119	    // SG11 cosine-gate temperature: gate = sigmoid(gate_temp * cos(grad, momentum))
120	    // (the canonical sg11_finalize_gate). Defaulted for back-compat callers; the
121	    // cosine SIGNAL is preserved, only the final squashing is the temp-scaled sigmoid.
122	    float gate_temp = 5.0f
123	) {
124	    for (size_t i = 0; i < params.size(); i++) {
125	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
126	        auto& p = params[i];
127	        auto& g = grads[i];
128	        auto& m = exp_avgs[i];
129	        auto& v = exp_avg_sqs[i];
130	        auto& mu = mu_bufs[i];
131	
132	        // Sweep A: meta-net forward
133	        auto x = torch::stack({g.to(torch::kFloat32).view({-1}),
134	                               sharpnesses[i].view({-1})}, /*dim=*/1);
135	        auto h = torch::gelu(torch::matmul(x, phi_W1.t()) + phi_b1);  // exact GELU (canonical PyTorch meta-net)
136	        auto mu_flat = (torch::matmul(h, phi_W2.unsqueeze(1)) + phi_b2).view_as(g);
137	        mu.copy_(mu_flat);
138	
139	        // Cosine gate
140	        auto gf = g.to(torch::kFloat32);
141	        auto mom = momenta[i];
142	#if defined(__HIPCC__)
143	        // LIVE (hipcc): §5 cosine-gate reduce — one pass yields num=Σg·m,
144	        // den_g=Σg², den_m=Σm² via DPP wave→block→AGENT atomics (replacing the
145	        // ATen .sum()/.norm() triple). gate = sigmoid(gate_temp·num/sqrt(den_g·den_m)).
146	        float gate;
147	        {
148	            auto gfc  = gf.contiguous();
149	            auto momc = mom.to(torch::kFloat32).contiguous();
150	            const int64_t n = static_cast<int64_t>(gfc.numel());  // Stage 1: 64-bit
151	            auto acc = torch::zeros({3}, gfc.options());
152	            hipStream_t stream = at::hip::getCurrentHIPStream();
153	            dim3 grid(static_cast<unsigned>(
154	                std::min<int64_t>(1024, (n + 255) / 256))), block(256);
155	            hipLaunchKernelGGL(native::supergrok11_gfx942_cosine_reduce, grid, block,
156	                               0, stream, gfc.data_ptr<float>(), momc.data_ptr<float>(),
157	                               acc.data_ptr<float>(), acc.data_ptr<float>() + 1,
158	                               acc.data_ptr<float>() + 2, n);
159	            SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
160	            auto h_acc = acc.cpu();
161	            float num   = h_acc[0].item<float>();
162	            float den_g = h_acc[1].item<float>();
163	            float den_m = h_acc[2].item<float>();
164	            float denom = sqrtf(den_g * den_m);
165	            float cos = (denom > 1e-12f) ? (num / denom) : 0.0f;
166	            gate = 1.0f / (1.0f + expf(-gate_temp * cos));  // sigmoid(gate_temp*cos)
167	        }
168	#else
169	        float dot = (gf * mom).sum().item<float>();
170	        float ng = gf.norm().item<float>();
171	        float nm = mom.norm().item<float>();
172	        float cos = (ng * nm > 1e-12f) ? (dot / (ng * nm)) : 0.0f;
173	        float gate = 1.0f / (1.0f + expf(-gate_temp * cos));  // sigmoid(gate_temp*cos)
174	#endif
175	
176	        // Sweep B: smart_grad + Adam
177	#if defined(__HIPCC__)
178	        // LIVE device path: the §5.APPLY f32x4-vectorized smart_grad + Adam
179	        // kernel fuses smart=g+(1-gate)*alpha*mu, the m/v EMAs, and the bias-
180	        // corrected decoupled-WD apply into ONE launch (128-bit dwordx4 access).
181	        {
182	            auto gfc = gf.contiguous();
183	            auto muc = mu.to(torch::kFloat32).contiguous();
184	            const int64_t n = static_cast<int64_t>(gfc.numel());  // Stage 1: 64-bit
185	            if (n > 0) {
186	                hipStream_t stream = at::hip::getCurrentHIPStream();
187	                dim3 grid(static_cast<unsigned>(
188	                    std::min<int64_t>(1024, (n + 255) / 256))), block(256);
189	                hipLaunchKernelGGL((native::supergrok11_gfx942_apply<float, float>),
190	                                   grid, block, 0, stream,
191	                                   p.data_ptr<float>(), m.data_ptr<float>(),
192	                                   v.data_ptr<float>(), muc.data_ptr<float>(),
193	                                   gfc.data_ptr<float>(), gate, alpha,
194	                                   lr, beta1, beta2, eps, wd, bc1, bc2, n);
195	                SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
196	            }
197	        }
198	#else
199	        auto smart = gf + (1.0f - gate) * alpha * mu;
200	        prim::ema_update_inplace(m, smart, beta1);
201	        prim::ema_sq_update_inplace(v, smart, beta2);
202	        prim::adam_apply_inplace(p, m, v, lr, bc1, bc2, eps, wd);
203	#endif
204	    }
205	}
