208	void launch_sg11_mu_metanet(
209	    torch::Tensor mu, torch::Tensor grad, torch::Tensor sharpness, torch::Tensor smart_grad, float alpha, torch::Tensor W1, torch::Tensor b1, torch::Tensor W2, torch::Tensor b2, float rescale, int hidden_dim
210	) {
211	    // phi network forward: 2-input MLP with GELU activation (canonical)
212	    auto gf = grad.to(torch::kFloat32).view({-1});
213	    auto sf = sharpness.view({-1});
214	    auto x = torch::stack({gf, sf}, /*dim=*/1);  // [N, 2]
215	    auto h = torch::gelu(torch::matmul(x, W1.t()) + b1);  // exact GELU (canonical PyTorch meta-net)
216	    float b2_val = b2.item<float>();
217	    auto mu_flat = (torch::matmul(h, W2.unsqueeze(1)) + b2_val).view_as(grad) * rescale;
218	    mu.copy_(mu_flat);
219	    // smart_grad = grad + alpha * mu
220	    smart_grad.copy_(gf.view_as(grad) + alpha * mu_flat);
221	}
222	
223	void launch_sg11_adam_decay(
224	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq, torch::Tensor smart_grad, torch::Tensor mu, float lamb_eff, float beta1, float beta2, float lr, float wd_eff, float eps, float bc1, float bc2
225	) {
226	    // g = smart_grad + lamb_eff * mu, then Adam update
227	    auto g = smart_grad + lamb_eff * mu;
228	    prim::ema_update_inplace(exp_avg, g, beta1);
229	    prim::ema_sq_update_inplace(exp_avg_sq, g, beta2);
230	    prim::adam_apply_inplace(param, exp_avg, exp_avg_sq, lr, bc1, bc2, eps, wd_eff);
231	}
232	
233	void launch_sg11_sam_perturb(
234	    torch::Tensor param, torch::Tensor grad, float rho_over_norm
235	) {
236	    // param += rho_over_norm * grad
237	    param.add_(grad.to(param.scalar_type()), rho_over_norm);
238	}
