240	void launch_sg11_sharpness_restore(
241	    torch::Tensor param, torch::Tensor sharpness, torch::Tensor backup, torch::Tensor sam_grad, torch::Tensor normal_grad
242	) {
243	    // param = backup, sharpness = (sam_grad - normal_grad)^2
244	    param.copy_(backup);
245	    auto diff = sam_grad.to(torch::kFloat32) - normal_grad.to(torch::kFloat32);
246	    sharpness.copy_(diff * diff);
247	}
