249	float compute_cosine_gate_fused(
250	    torch::Tensor smart_grad, torch::Tensor mu, float gate_temp
251	) {
252	    // gate = sigmoid(gate_temp * cos_sim(smart_grad, mu)) — the canonical
253	    // sg11_finalize_gate (csrc/algorithms/supergrok11.h). The cosine SIGNAL is the
254	    // SG11 discriminator; only the final squashing is the temp-scaled sigmoid.
255	    auto sg_f = smart_grad.to(torch::kFloat32).flatten().contiguous();
256	    auto mu_f = mu.to(torch::kFloat32).flatten().contiguous();
257	#if defined(__HIPCC__)
258	    // LIVE (hipcc): §5 cosine-gate reduce (num=Σsg·mu, den_g=Σsg², den_m=Σmu²)
259	    // via DPP wave→block→AGENT atomics; ATen .sum() triple is the #else fallback.
260	    const int64_t n = static_cast<int64_t>(sg_f.numel());  // Stage 1: 64-bit
261	    auto acc = torch::zeros({3}, sg_f.options());
262	    hipStream_t stream = at::hip::getCurrentHIPStream();
263	    dim3 grid(static_cast<unsigned>(
264	        std::min<int64_t>(1024, (n + 255) / 256))), block(256);
265	    hipLaunchKernelGGL(native::supergrok11_gfx942_cosine_reduce, grid, block,
266	                       0, stream, sg_f.data_ptr<float>(), mu_f.data_ptr<float>(),
267	                       acc.data_ptr<float>(), acc.data_ptr<float>() + 1,
268	                       acc.data_ptr<float>() + 2, n);
269	    SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
270	    auto h_acc = acc.cpu();
271	    float num = h_acc[0].item<float>(), den_g = h_acc[1].item<float>(), den_m = h_acc[2].item<float>();
272	    float denom = sqrtf(den_g * den_m + 1e-12f);
273	    float cos = (denom > 0.0f) ? (num / denom) : 0.0f;
274	    return 1.0f / (1.0f + expf(-gate_temp * cos));
275	#else
276	    float num = (sg_f * mu_f).sum().item<float>();
277	    float den_g = (sg_f * sg_f).sum().item<float>();
278	    float den_m = (mu_f * mu_f).sum().item<float>();
279	    float denom = sqrtf(den_g * den_m + 1e-12f);
280	    float cos = (denom > 0.0f) ? (num / denom) : 0.0f;
281	    return 1.0f / (1.0f + expf(-gate_temp * cos));
282	#endif
283	}
