344	// §5  AMD-NATIVE device kernel (Stage 5 hand-written AMDGCN).
345	//
346	// The cosine-gate 3-quantity reduction: THREE parallel global sums in one pass,
347	//   num   = Σ_i g_i · m_i        (g·m dot product)
348	//   den_g = Σ_i g_i²             (‖g‖² )
349	//   den_m = Σ_i m_i²             (‖m‖² )
350	// then on the host: gate = sigmoid(gate_temp · num / sqrt(den_g·den_m + 1e-12)).
351	// Each thread accumulates all THREE partials, then we run THREE independent
352	// wave→block→AGENT-atomic trees (the standard 2-level tree from the spec):
353	//   1. each thread grid-strides, accumulating num/den_g/den_m;
354	//   2. amd::wave_reduce_add_dpp on each → per-wavefront sums (§2.6);
355	//   3. lane 0 of each wavefront writes the three quantities to LDS slots;
356	//      workgroup_barrier;
357	//   4. the first wavefront reduces each slot array via a second DPP reduce;
358	//   5. one thread does three amd::atomic_add_agent_f32 (num/den_g/den_m accs)
359	//      (§2.13: AGENT-scope atomics, visible across all 8 XCDs of MI300X).
360	// APPLY: the per-element meta-net MLP + smart_grad + Adam apply stays on the
361	// ATen host path (launch_supergrok11_step) — only the cosine-gate reduction is
362	// migrated to AMDGCN.
363	// ============================================================================
364	namespace sg { namespace gfx942 { namespace native {
365	
366	namespace amd = ::sg::gfx942::amdgcn;
367	static constexpr int kWave = 64;   // == amd::kWave (CDNA3 wavefront width)
368	
369	// Stage-1 NaN/Inf gradient sanitization (mirror of sm_90 sg_sanitize_grad).
370	// Identity unless built with -DSG_SANITIZE_NONFINITE=1; applied on the APPLY
371	// path's grad read only (the cosine reduction is unchanged). Default byte-identical.
372	#ifndef SG_SANITIZE_NONFINITE
373	#define SG_SANITIZE_NONFINITE 0
374	#endif
375	__device__ __forceinline__ float sg_sanitize_grad(float g) {
376	#if SG_SANITIZE_NONFINITE
377	    return __builtin_isfinite(g) ? g : 0.0f;
378	#else
379	    return g;
380	#endif
381	}
382	
383	// Block (workgroup) cosine-gate 3-quantity reduction over `[0..n)`, three
384	// AGENT atomics. blockDim.x must be a multiple of kWave and <= kWave*kWave
385	// (<= 4096); LDS holds one float per wavefront per quantity (<= 3*64 floats).
386	__device__ __forceinline__ void supergrok11_cosine_block(
387	    const float* __restrict__ g, const float* __restrict__ m,
388	    float* __restrict__ num_acc, float* __restrict__ den_g_acc,
389	    float* __restrict__ den_m_acc, int64_t n)
390	{
391	    // LDS/lane bookkeeping is LOCAL to the block (<= 4096 threads) → int. The
392	    // GLOBAL element index/stride is int64 so the reduction cannot wrap (Stage 1).
393	    const int tid    = static_cast<int>(threadIdx.x);
394	    const int lane   = tid % kWave;
395	    const int waveId = tid / kWave;
396	    const int wpb    = static_cast<int>(blockDim.x) / kWave;
397	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x + tid;
398	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
399	
400	    float num = 0.f, den_g = 0.f, den_m = 0.f;
401	    for (int64_t i = gtid; i < n; i += stride) {
402	        // g is the read-once grad (nontemporal/streaming is correct); m is the
403	        // recurring momentum STATE, reused next step → CACHED (keep L2-resident).
404	        float gi = amd::streaming_load(&g[i]);
405	        float mi = amd::cached_load(&m[i]);
406	        num   += gi * mi;
407	        den_g += gi * gi;
408	        den_m += mi * mi;
409	    }
410	    // three wavefront DPP reduces: every lane holds the wavefront sums.
411	    num   = amd::wave_reduce_add_dpp(num);
412	    den_g = amd::wave_reduce_add_dpp(den_g);
413	    den_m = amd::wave_reduce_add_dpp(den_m);
414	
415	    __shared__ float lds_num[kWave];
416	    __shared__ float lds_dg[kWave];
417	    __shared__ float lds_dm[kWave];
418	    if (lane == 0) {
419	        lds_num[waveId] = num;
420	        lds_dg[waveId]  = den_g;
421	        lds_dm[waveId]  = den_m;
422	    }
423	    amd::workgroup_barrier_release();
424	
425	    // first wavefront reduces each per-wavefront slot array, then three atomics.
426	    if (waveId == 0) {
427	        float sn = (lane < wpb) ? lds_num[lane] : 0.f;
428	        float sg = (lane < wpb) ? lds_dg[lane]  : 0.f;
429	        float sm = (lane < wpb) ? lds_dm[lane]  : 0.f;
430	        sn = amd::wave_reduce_add_dpp(sn);
431	        sg = amd::wave_reduce_add_dpp(sg);
432	        sm = amd::wave_reduce_add_dpp(sm);
433	        if (lane == 0) {
434	            amd::atomic_add_agent_f32(num_acc,   sn);
435	            amd::atomic_add_agent_f32(den_g_acc, sg);
436	            amd::atomic_add_agent_f32(den_m_acc, sm);
437	        }
438	    }
439	}
