441	// Bandwidth-bound reduction → request high occupancy (256-thread block = 4
442	// wavefronts; 8 waves/EU) to hide global-memory latency. (WS5 occupancy wire.)
443	extern "C" SG_KERNEL_BOUNDS(256, 8) void supergrok11_gfx942_cosine_reduce(
444	    const float* __restrict__ g, const float* __restrict__ m,
445	    float* __restrict__ num_acc, float* __restrict__ den_g_acc,
446	    float* __restrict__ den_m_acc, int64_t n)
447	{
448	    supergrok11_cosine_block(g, m, num_acc, den_g_acc, den_m_acc, n);
449	}
