451	// ── §5.APPLY  per-element smart_grad + Adam apply (128-bit / f32x4 vectorized) ─
452	// smart = g + (1-gate)*alpha*mu, then the m/v EMA + bias-corrected decoupled-WD
453	// apply — BIT-IDENTICAL to the ATen host path (primitives.hpp):
454	//   m   = beta1*m + (1-beta1)*smart
455	//   v   = beta2*v + (1-beta2)*smart*smart
456	//   m_hat = m/bc1 ; v_hat = v/bc2 ; denom = sqrt(v_hat)+eps
457	//   p  -= lr*(m_hat/denom + wd*p)
458	// The reduced `gate` is uniform (host-computed); alpha is a scalar. Memory access
459	// widens to 128-bit dwordx4 (f32x4 streaming_load / streaming_store on
460	// param/exp_avg/exp_avg_sq/mu/grad); the scalar tail runs the identical math on
461	// the n%4 remainder. Per-lane math, order, constants and __builtin_sqrtf are
462	// unchanged from the scalar form — only the access width changes.
463	using f32x4 = ::sg::gfx942::amdgcn::f32x4;
464	
465	// Identical per-element apply (used by both the f32x4 lanes and the scalar tail).
466	__device__ __forceinline__ float sg11_apply_elem(
467	    float* __restrict__ pp, float* __restrict__ pm, float* __restrict__ pv,
468	    float mu_i, float g_i, float gate, float alpha,
469	    float lr, float beta1, float beta2, float eps, float wd,
470	    float bc1, float bc2)
471	{
472	    float smart = g_i + (1.0f - gate) * alpha * mu_i;
473	    float m = beta1 * (*pm) + (1.0f - beta1) * smart;
474	    float v = beta2 * (*pv) + (1.0f - beta2) * smart * smart;
475	    *pm = m;
476	    *pv = v;
477	    float m_hat = m / bc1;
478	    float v_hat = v / bc2;
479	    float denom = __builtin_sqrtf(v_hat) + eps;
480	    float update = m_hat / denom + wd * (*pp);
481	    return (*pp) - lr * update;
482	}
483	
484	template <typename ParamT, typename GradT>
485	SG_KERNEL_BOUNDS(256, 8) void supergrok11_gfx942_apply(
486	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
487	    float* __restrict__ exp_avg_sq, const float* __restrict__ mu,
488	    const GradT* __restrict__ grad, float gate, float alpha,
489	    float lr, float beta1, float beta2, float eps, float wd,
490	    float bc1, float bc2, int64_t N)
491	{
492	    // 64-bit grid-stride indexing (Stage 1): cast BEFORE the multiply.
493	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x
494	                       + threadIdx.x;
495	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
496	    const int64_t n4     = N & ~static_cast<int64_t>(3);   // largest mult of 4 <= N
497	
498	    // Vectorized body: 4 contiguous floats / iter via f32x4 (128-bit access).
499	    // NONTEMPORAL POLICY (matches adamw_gfx942): grad + mu are read-once this
500	    // step → streaming (nontemporal, L2-bypass); exp_avg / exp_avg_sq are
501	    // recurring STATE (read+written every step, reused next step) → CACHED;
502	    // param is read once then written once → cached load + streaming store.
503	    for (int64_t base = gtid * 4; base < n4; base += stride * 4) {
504	        f32x4 pv4 = amd::cached_load(reinterpret_cast<const f32x4*>(param + base));
505	        f32x4 mv4 = amd::cached_load(reinterpret_cast<const f32x4*>(exp_avg + base));
506	        f32x4 vv4 = amd::cached_load(reinterpret_cast<const f32x4*>(exp_avg_sq + base));
507	        f32x4 uv4 = amd::streaming_load(reinterpret_cast<const f32x4*>(mu + base));
508	        f32x4 gv4 = amd::streaming_load(reinterpret_cast<const f32x4*>(grad + base));
509	        f32x4 ov4;
510	        #pragma unroll
511	        for (int j = 0; j < 4; ++j) {
512	            float pj = pv4[j], mj = mv4[j], vj = vv4[j];
513	            ov4[j] = sg11_apply_elem(&pj, &mj, &vj, uv4[j],
514	                                     sg_sanitize_grad(gv4[j]), gate, alpha,
515	                                     lr, beta1, beta2, eps, wd, bc1, bc2);
516	            mv4[j] = mj;
517	            vv4[j] = vj;
518	        }
519	        amd::cached_store(reinterpret_cast<f32x4*>(exp_avg + base), mv4);
520	        amd::cached_store(reinterpret_cast<f32x4*>(exp_avg_sq + base), vv4);
521	        amd::streaming_store(reinterpret_cast<f32x4*>(param + base), ov4);
522	    }
523	
524	    // Scalar tail: the n%4 remainder, identical per-element function.
525	    for (int64_t i = n4 + gtid; i < N; i += stride) {
526	        float pi = param[i], mi = exp_avg[i], vi = exp_avg_sq[i];
527	        float out = sg11_apply_elem(&pi, &mi, &vi, mu[i],
528	                                    sg_sanitize_grad(grad[i]), gate, alpha,
529	                                    lr, beta1, beta2, eps, wd, bc1, bc2);
530	        exp_avg[i]    = mi;
531	        exp_avg_sq[i] = vi;
532	        param[i]      = out;
533	    }
534	}
