99	void launch_supergrok15_step(
100	    std::vector<torch::Tensor>& params,
101	    std::vector<torch::Tensor>& exp_avgs,
102	    std::vector<torch::Tensor>& exp_avg_sqs,
103	    std::vector<torch::Tensor>& mu_bufs,
104	    std::vector<torch::Tensor>& grads,
105	    std::vector<torch::Tensor>& sharpnesses,
106	    const torch::Tensor& phi_W1,
107	    const torch::Tensor& phi_b1,
108	    const torch::Tensor& phi_W2,
109	    float phi_b2,
110	    float gate_global,
111	    float alpha_base, float alpha_max,
112	    float lr, float beta1, float beta2, float eps, float wd,
113	    float bc1, float bc2
114	) {
115	    for (size_t i = 0; i < params.size(); i++) {
116	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
117	        auto& p = params[i];
118	        auto& g = grads[i];
119	        auto& m = exp_avgs[i];
120	        auto& v = exp_avg_sqs[i];
121	        auto& mu = mu_bufs[i];
122	
123	        // Sweep A: meta-net forward
124	        auto x = torch::stack({g.to(torch::kFloat32).view({-1}),
125	                               sharpnesses[i].view({-1})}, /*dim=*/1);
126	        auto h = torch::gelu(torch::matmul(x, phi_W1.t()) + phi_b1);  // exact GELU (canonical PyTorch meta-net)
127	        auto mu_flat = (torch::matmul(h, phi_W2.unsqueeze(1)) + phi_b2).view_as(g);
128	        mu.copy_(mu_flat);
129	
130	        // Per-coord alpha gate signal: the sharpness-driven scale.
131	        float gate = gate_global;
132	#if defined(__HIPCC__)
133	        // LIVE (hipcc): §5 sharpness reduce — one pass yields acc = Σ_i
134	        // sharpness_i via DPP wave→block→AGENT atomics (replacing an ATen
135	        // .sum()). The host forms the sharpness-driven gate scale from the mean
136	        // and folds it into the externally-supplied gate_global.
137	        {
138	            auto sh = sharpnesses[i].to(torch::kFloat32).contiguous();
139	            const int64_t n = static_cast<int64_t>(sh.numel());  // Stage 1: 64-bit
140	            if (n > 0) {
141	                auto acc = torch::zeros({1}, sh.options());
142	                hipStream_t stream = at::hip::getCurrentHIPStream();
143	                dim3 grid(static_cast<unsigned>(
144	                    std::min<int64_t>(1024, (n + 255) / 256))), block(256);
145	                hipLaunchKernelGGL(native::supergrok15_gfx942_sharpness_reduce,
146	                                   grid, block, 0, stream,
147	                                   sh.data_ptr<float>(), acc.data_ptr<float>(), n);
148	                SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
149	                float sharp_mean = acc.item<float>() / static_cast<float>(n);
150	                gate = gate_global * (1.0f / (1.0f + sharp_mean));
151	            }
152	        }
153	#endif
154	
155	        // Sweep B: per-coord alpha gate + smart_grad + Adam apply.
156	#if defined(__HIPCC__)
157	        // LIVE device path: the §5.APPLY f32x4-vectorized kernel fuses
158	        // a_per_coord=clamp(alpha_base*(1+mu),0,alpha_max), smart=g+gate*a*mu,
159	        // the m/v EMAs, and the bias-corrected decoupled-WD apply into ONE launch
160	        // (128-bit dwordx4 access). Dispatched exactly like sg11 (the apply was
161	        // previously DEFINED but never launched — WS5/item 4). gate already folds
162	        // the on-device sharpness mean (above). The `#else` keeps the ATen path.
163	        {
164	            auto gfc = g.to(torch::kFloat32).contiguous();
165	            auto muc = mu.to(torch::kFloat32).contiguous();
166	            const int64_t n = static_cast<int64_t>(gfc.numel());  // Stage 1: 64-bit
167	            if (n > 0) {
168	                hipStream_t stream = at::hip::getCurrentHIPStream();
169	                dim3 grid(static_cast<unsigned>(
170	                    std::min<int64_t>(1024, (n + 255) / 256))), block(256);
171	                hipLaunchKernelGGL((native::supergrok15_gfx942_apply<float, float>),
172	                                   grid, block, 0, stream,
173	                                   p.data_ptr<float>(), m.data_ptr<float>(),
174	                                   v.data_ptr<float>(), muc.data_ptr<float>(),
175	                                   gfc.data_ptr<float>(), gate, alpha_base, alpha_max,
176	                                   lr, beta1, beta2, eps, wd, bc1, bc2, n);
177	                SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
178	            }
179	        }
180	#else
181	        // Per-coord alpha, then smart_grad
182	        auto a_per_coord = torch::clamp(alpha_base * (1.0f + mu), 0.0f, alpha_max);
183	        auto smart = g.to(torch::kFloat32) + gate * a_per_coord * mu;
184	
185	        prim::ema_update_inplace(m, smart, beta1);
186	        prim::ema_sq_update_inplace(v, smart, beta2);
187	        prim::adam_apply_inplace(p, m, v, lr, bc1, bc2, eps, wd);
188	#endif
189	    }
190	}
