288	// ============================================================================
289	// §5  AMD-NATIVE device kernel (Stage 5 hand-written AMDGCN).
290	//
291	// The sharpness reduction: the global gate signal Σ_i sharpness_i over the
292	// per-coordinate sharpness map (sharpness_i = (g_sam_i − g_i)², the SAM
293	// curvature proxy). The high-value AMDGCN piece is the global sum; the host
294	// forms the sharpness-driven gate scale from it (e.g. mean = Σ/n). This is the
295	// canonical 2-level (wave→block→grid) tree from the task spec:
296	//   1. each thread grid-strides sharpness_i, accumulating a per-thread partial;
297	//   2. amd::wave_reduce_add_dpp gives every lane the per-wavefront sum (§2.6);
298	//   3. lane 0 of each wavefront writes its sum to an LDS slot; workgroup_barrier;
299	//   4. the first wavefront reduces the LDS slots via a second DPP reduce;
300	//   5. one thread does amd::atomic_add_agent_f32 to the global accumulator
301	//      (§2.13: AMD has no DSMEM, so cross-workgroup uses an AGENT-scope atomic
302	//      visible across all 8 XCDs of MI300X).
303	// APPLY: the per-element meta-net MLP + per-coord alpha gate + smart_grad + Adam
304	// apply stays on the ATen host path (launch_supergrok15_step) — only the
305	// sharpness/gate-signal reduction is migrated to AMDGCN.
306	// ============================================================================
307	namespace sg { namespace gfx942 { namespace native {
308	
309	namespace amd = ::sg::gfx942::amdgcn;
310	static constexpr int kWave = 64;   // == amd::kWave (CDNA3 wavefront width)
311	
312	// Stage-1 NaN/Inf gradient sanitization (mirror of sm_90 sg_sanitize_grad).
313	// Identity unless built with -DSG_SANITIZE_NONFINITE=1; applied on the APPLY
314	// path's grad read only (the sharpness reduce is unchanged). Default byte-identical.
315	#ifndef SG_SANITIZE_NONFINITE
316	#define SG_SANITIZE_NONFINITE 0
317	#endif
318	__device__ __forceinline__ float sg_sanitize_grad(float g) {
319	#if SG_SANITIZE_NONFINITE
320	    return __builtin_isfinite(g) ? g : 0.0f;
321	#else
322	    return g;
323	#endif
324	}
325	
326	// Block (workgroup) sum of `sharpness[0..n)`, atomically added to *acc.
327	// blockDim.x must be a multiple of kWave and <= kWave*kWave (<= 4096); LDS holds
328	// one float per wavefront (<= 64 floats).
329	__device__ __forceinline__ void supergrok15_sharpness_block(
330	    const float* __restrict__ sharpness, float* __restrict__ acc, int64_t n)
331	{
332	    // LDS/lane bookkeeping is LOCAL to the block (<= 4096 threads) → int. The
333	    // GLOBAL element index/stride is int64 so the reduction cannot wrap (Stage 1).
334	    const int tid    = static_cast<int>(threadIdx.x);
335	    const int lane   = tid % kWave;
336	    const int waveId = tid / kWave;
337	    const int wpb    = static_cast<int>(blockDim.x) / kWave;
338	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x + tid;
339	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
340	
341	    float local = 0.f;
342	    for (int64_t i = gtid; i < n; i += stride) {
343	        local += amd::streaming_load(&sharpness[i]);
344	    }
345	    // wavefront DPP reduce: every lane holds the wavefront sum.
346	    local = amd::wave_reduce_add_dpp(local);
347	
348	    __shared__ float lds[kWave];
349	    if (lane == 0) lds[waveId] = local;
350	    amd::workgroup_barrier_release();
351	
352	    // first wavefront reduces the per-wavefront slots, then one AGENT atomic.
353	    if (waveId == 0) {
354	        float slot = (lane < wpb) ? lds[lane] : 0.f;
355	        slot = amd::wave_reduce_add_dpp(slot);
356	        if (lane == 0) amd::atomic_add_agent_f32(acc, slot);
357	    }
358	}
359	
360	// Bandwidth-bound reduction → request high occupancy (256-thread block = 4
361	// wavefronts; 8 waves/EU) to hide global-memory latency. (WS5 occupancy wire.)
362	extern "C" SG_KERNEL_BOUNDS(256, 8) void supergrok15_gfx942_sharpness_reduce(
363	    const float* __restrict__ sharpness, float* __restrict__ acc, int64_t n)
364	{
365	    supergrok15_sharpness_block(sharpness, acc, n);
366	}
367	
368	// ── §5.APPLY  per-element smart_grad + Adam apply (128-bit / f32x4 vectorized) ─
369	// Per-coord alpha gate + smart_grad + Adam, BIT-IDENTICAL to the ATen host path
370	// (launch_supergrok15_step + primitives.hpp):
371	//   a_per_coord = clamp(alpha_base*(1+mu), 0, alpha_max)
372	//   smart       = g + gate*a_per_coord*mu
373	//   m   = beta1*m + (1-beta1)*smart
374	//   v   = beta2*v + (1-beta2)*smart*smart
375	//   m_hat = m/bc1 ; v_hat = v/bc2 ; denom = sqrt(v_hat)+eps
376	//   p  -= lr*(m_hat/denom + wd*p)
377	// `gate` (the sharpness-folded gate_global) is uniform; alpha_base/alpha_max are
378	// scalars; the per-coordinate alpha is recomputed per element. Memory access
379	// widens to 128-bit dwordx4 (f32x4 streaming_load/streaming_store on
380	// param/exp_avg/exp_avg_sq/mu/grad); the scalar tail runs the identical math on
381	// the n%4 remainder. Per-lane math, order, constants and __builtin_sqrtf are
382	// unchanged from the scalar form — only the access width changes.
383	using f32x4 = ::sg::gfx942::amdgcn::f32x4;
384	
385	__device__ __forceinline__ float sg15_clampf(float x, float lo, float hi) {
386	    // Matches torch::clamp(x, lo, hi) element semantics.
387	    return __builtin_fminf(__builtin_fmaxf(x, lo), hi);
388	}
389	
390	// Identical per-element apply (used by both the f32x4 lanes and the scalar tail).
391	__device__ __forceinline__ float sg15_apply_elem(
392	    float* __restrict__ pp, float* __restrict__ pm, float* __restrict__ pv,
393	    float mu_i, float g_i, float gate, float alpha_base, float alpha_max,
394	    float lr, float beta1, float beta2, float eps, float wd,
395	    float bc1, float bc2)
396	{
397	    float a_per_coord = sg15_clampf(alpha_base * (1.0f + mu_i), 0.0f, alpha_max);
398	    float smart = g_i + gate * a_per_coord * mu_i;
399	    float m = beta1 * (*pm) + (1.0f - beta1) * smart;
400	    float v = beta2 * (*pv) + (1.0f - beta2) * smart * smart;
401	    *pm = m;
402	    *pv = v;
403	    float m_hat = m / bc1;
404	    float v_hat = v / bc2;
405	    float denom = __builtin_sqrtf(v_hat) + eps;
406	    float update = m_hat / denom + wd * (*pp);
407	    return (*pp) - lr * update;
408	}
409	
410	template <typename ParamT, typename GradT>
411	SG_KERNEL_BOUNDS(256, 8) void supergrok15_gfx942_apply(
412	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
413	    float* __restrict__ exp_avg_sq, const float* __restrict__ mu,
414	    const GradT* __restrict__ grad, float gate, float alpha_base, float alpha_max,
415	    float lr, float beta1, float beta2, float eps, float wd,
416	    float bc1, float bc2, int64_t N)
417	{
418	    // 64-bit grid-stride indexing (Stage 1): cast BEFORE the multiply.
419	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x
420	                       + threadIdx.x;
421	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
422	    const int64_t n4     = N & ~static_cast<int64_t>(3);   // largest mult of 4 <= N
423	
424	    // Vectorized body: 4 contiguous floats / iter via f32x4 (128-bit access).
425	    // NONTEMPORAL POLICY (matches adamw_gfx942): grad + mu are read-once this
426	    // step → streaming (nontemporal, L2-bypass); exp_avg / exp_avg_sq are
427	    // recurring STATE (read+written every step, reused next step) → CACHED;
428	    // param is read once then written once → cached load + streaming store.
429	    for (int64_t base = gtid * 4; base < n4; base += stride * 4) {
430	        f32x4 pv4 = amd::cached_load(reinterpret_cast<const f32x4*>(param + base));
431	        f32x4 mv4 = amd::cached_load(reinterpret_cast<const f32x4*>(exp_avg + base));
432	        f32x4 vv4 = amd::cached_load(reinterpret_cast<const f32x4*>(exp_avg_sq + base));
433	        f32x4 uv4 = amd::streaming_load(reinterpret_cast<const f32x4*>(mu + base));
434	        f32x4 gv4 = amd::streaming_load(reinterpret_cast<const f32x4*>(grad + base));
435	        f32x4 ov4;
436	        #pragma unroll
437	        for (int j = 0; j < 4; ++j) {
438	            float pj = pv4[j], mj = mv4[j], vj = vv4[j];
439	            ov4[j] = sg15_apply_elem(&pj, &mj, &vj, uv4[j],
440	                                     sg_sanitize_grad(gv4[j]), gate,
441	                                     alpha_base, alpha_max,
442	                                     lr, beta1, beta2, eps, wd, bc1, bc2);
443	            mv4[j] = mj;
444	            vv4[j] = vj;
445	        }
446	        amd::cached_store(reinterpret_cast<f32x4*>(exp_avg + base), mv4);
447	        amd::cached_store(reinterpret_cast<f32x4*>(exp_avg_sq + base), vv4);
448	        amd::streaming_store(reinterpret_cast<f32x4*>(param + base), ov4);
449	    }
450	
451	    // Scalar tail: the n%4 remainder, identical per-element function.
452	    for (int64_t i = n4 + gtid; i < N; i += stride) {
453	        float pi = param[i], mi = exp_avg[i], vi = exp_avg_sq[i];
454	        float out = sg15_apply_elem(&pi, &mi, &vi, mu[i],
455	                                    sg_sanitize_grad(grad[i]), gate,
456	                                    alpha_base, alpha_max,
457	                                    lr, beta1, beta2, eps, wd, bc1, bc2);
458	        exp_avg[i]    = mi;
459	        exp_avg_sq[i] = vi;
460	        param[i]      = out;
461	    }
462	}
